import os
import sys
import json
import logging
import argparse
from pathlib import Path
import numpy as np
import pandas as pd

# Import the decomposition logic from metrics.py
from uq.metrics import decompose_uncertainty

# Setup logging
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)
logger = logging.getLogger(__name__)

def load_base_predictions(base_path: str) -> pd.DataFrame:
    """Load the base predictions CSV generated by T016a/T016b."""
    if not os.path.exists(base_path):
        raise FileNotFoundError(f"Base predictions file not found: {base_path}")
    logger.info(f"Loading base predictions from {base_path}")
    df = pd.read_csv(base_path)
    required_cols = ['sample_id', 'method', 'prediction', 'variance', 'lower_50', 'upper_50', 'lower_90', 'upper_90']
    missing = [c for c in required_cols if c not in df.columns]
    if missing:
        raise ValueError(f"Base predictions missing required columns: {missing}")
    return df

def decompose_uncertainty_for_method(df: pd.DataFrame, method: str) -> tuple:
    """
    Calculate aleatoric and epistemic uncertainty for a specific method.
    
    For Deep Ensemble and MC Dropout:
      - We need to aggregate across samples to get global statistics or per-sample if available.
      - The base CSV has one row per sample. To decompose, we typically need the variance of means (epistemic)
        and mean of variances (aleatoric).
      - Since the base CSV aggregates the prediction and variance per sample, we cannot re-calculate
        per-sample decomposition without the raw ensemble outputs.
      - HOWEVER, the task description for T022a says:
        "Epistemic variance = variance of means across samples", "Aleatoric variance = mean of predicted variances".
      - This implies a global decomposition for the method on the test set, OR we treat the 'prediction'
        column as the mean and 'variance' as the predicted variance.
      - If we treat it as global stats for the method:
        Epistemic = Variance(predictions) across all samples for this method.
        Aleatoric = Mean(variances) across all samples for this method.
      - This aligns with the T022a description if we interpret "across samples" as the dataset samples.
    
    For Sparse GP:
      - Aleatoric and Epistemic are set to null/NaN.
    """
    subset = df[df['method'] == method].copy()
    if subset.empty:
        logger.warning(f"No data found for method: {method}")
        return np.nan, np.nan, np.nan

    if method == 'sparse_gp':
        logger.info(f"Setting aleatoric/epistemic to null for Sparse GP method")
        return np.nan, np.nan, np.nan

    # Calculate global aleatoric and epistemic for this method on the test set
    # Epistemic: Variance of the predictions (means) across the test set samples
    # Aleatoric: Mean of the predicted variances across the test set samples
    # Note: This is a global decomposition for the method's performance on the set.
    # If per-sample decomposition were needed, we would need the raw ensemble outputs (n_samples, n_models).
    # Given the input is aggregated, we calculate the aggregate decomposition.
    
    predictions = subset['prediction'].values
    variances = subset['variance'].values

    epistemic = np.var(predictions)
    aleatoric = np.mean(variances)
    total = aleatoric + epistemic

    return aleatoric, epistemic, total

def process_sparse_gp(df: pd.DataFrame) -> pd.DataFrame:
    """Explicitly handle Sparse GP rows to ensure nulls."""
    # Identify Sparse GP rows
    gp_mask = df['method'] == 'sparse_gp'
    if gp_mask.any():
        df.loc[gp_mask, 'aleatoric'] = np.nan
        df.loc[gp_mask, 'epistemic'] = np.nan
        # For GP, total is just the variance (as per T022a condition)
        # But the decomposition logic usually sums them. The task says "total to variance".
        # We will set total to variance for GP rows specifically.
        df.loc[gp_mask, 'total'] = df.loc[gp_mask, 'variance']
    return df

def decompose_uncertainty(df: pd.DataFrame) -> pd.DataFrame:
    """
    Main decomposition function.
    Iterates over unique methods, calculates metrics, and updates the dataframe.
    """
    methods = df['method'].unique()
    
    # Prepare columns
    df['aleatoric'] = np.nan
    df['epistemic'] = np.nan
    df['total'] = np.nan
    df['uncertainty_type'] = ''

    for method in methods:
        aleatoric, epistemic, total = decompose_uncertainty_for_method(df, method)
        
        # Assign to all rows of this method
        mask = df['method'] == method
        df.loc[mask, 'aleatoric'] = aleatoric
        df.loc[mask, 'epistemic'] = epistemic
        df.loc[mask, 'total'] = total
        
        # Determine uncertainty type based on method
        if method == 'sparse_gp':
            df.loc[mask, 'uncertainty_type'] = 'aleatoric' # GP typically models aleatoric in variance, epistemic in kernel, but task says null/null/total=var
        elif method in ['deep_ensemble', 'mc_dropout']:
            df.loc[mask, 'uncertainty_type'] = 'mixed'
        else:
            df.loc[mask, 'uncertainty_type'] = 'unknown'

    # Ensure Sparse GP specific logic (total = variance, aleatoric/epistemic null) is strictly enforced
    # The loop above sets total = aleatoric + epistemic which would be NaN + NaN = NaN for GP.
    # We need to fix total for GP to be just the variance.
    gp_mask = df['method'] == 'sparse_gp'
    if gp_mask.any():
        df.loc[gp_mask, 'total'] = df.loc[gp_mask, 'variance']
        df.loc[gp_mask, 'aleatoric'] = np.nan
        df.loc[gp_mask, 'epistemic'] = np.nan

    return df

def main():
    parser = argparse.ArgumentParser(description='Decompose uncertainty and update predictions CSV')
    parser.add_argument('--input', type=str, default='results/uq_predictions_base.csv',
                        help='Path to the base predictions CSV')
    parser.add_argument('--output', type=str, default='results/uq_predictions.csv',
                        help='Path to save the updated predictions CSV')
    args = parser.parse_args()

    logger.info(f"Starting decomposition for {args.input}")
    
    try:
        # 1. Load base predictions
        df = load_base_predictions(args.input)
        
        # 2. Decompose uncertainty
        df = decompose_uncertainty(df)
        
        # 3. Ensure column order matches requirements
        # Required: sample_id, method, prediction, variance, lower_50, upper_50, lower_90, upper_90, 
        #           aleatoric, epistemic, total, uncertainty_type
        expected_cols = [
            'sample_id', 'method', 'prediction', 'variance', 
            'lower_50', 'upper_50', 'lower_90', 'upper_90',
            'aleatoric', 'epistemic', 'total', 'uncertainty_type'
        ]
        
        # Check if all expected columns exist (they should after decomposition)
        missing_cols = [c for c in expected_cols if c not in df.columns]
        if missing_cols:
            raise ValueError(f"Missing columns after decomposition: {missing_cols}")
        
        # Reorder
        df = df[expected_cols]
        
        # 4. Save to CSV with na_rep=''
        logger.info(f"Saving results to {args.output}")
        df.to_csv(args.output, index=False, na_rep='')
        
        logger.info(f"Successfully generated {args.output}")
        print(f"Output written to {args.output}")
        
    except Exception as e:
        logger.error(f"Failed to process predictions: {e}")
        raise

if __name__ == '__main__':
    main()